B.afD=s(["Davac\u0131n\u0131n davas\u0131ndan vazge\xe7mesidir.","Daval\u0131n\u0131n, davac\u0131n\u0131n talep sonucuna k\u0131smen veya tamamen muvafakat etmesidir.","Taraflar\u0131n uzla\u015fmas\u0131d\u0131r.","Mahkemenin davay\u0131 kabul etmesidir."],t.s)
B.avD=new A.bx("taraf_02",B.f1,"Kabul nedir?",B.afD,1,"HMK m. 308: Kabul, davac\u0131n\u0131n talep sonucuna daval\u0131n\u0131n k\u0131smen veya tamamen muvafakat etmesidir.")
B.akk=s(["Evet, her ikisi de kar\u015f\u0131 taraf\u0131n kabul\xfcne ba\u011fl\u0131d\u0131r.","Hay\u0131r; feragat ve kabul tek tarafl\u0131 irade beyan\u0131yla sonu\xe7 do\u011furur, kar\u015f\u0131 taraf\u0131n veya mahkemenin muvafakatine gerek yoktur.","Yaln\u0131zca h\xe2kimin onay\u0131yla ge\xe7erli olur.","Yaln\u0131zca noter huzurunda yap\u0131l\u0131rsa ge\xe7erlidir."],t.s)
